def largest_subset(nums):
    if not nums:
        return 0

    nums.sort()
    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
