def maxAverageOfPath(matrix):
    N = len(matrix)
    dp = [[(0, 0)] * N for _ in range(N)]  # Each cell: (total_cost, cells_count)

    dp[0][0] = (matrix[0][0], 1)

    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i > 0:
                above_cost, above_count = dp[i-1][j]
                above_cost += matrix[i][j]
                above_count += 1
            else:
                above_cost, above_count = float('-inf'), 0

            if j > 0:
                left_cost, left_count = dp[i][j-1]
                left_cost += matrix[i][j]
                left_count += 1
            else:
                left_cost, left_count = float('-inf'), 0

            if above_cost / above_count > left_cost / left_count:
                dp[i][j] = (above_cost, above_count)
            else:
                dp[i][j] = (left_cost, left_count)

    total_cost, cells_count = dp[N-1][N-1]
    return total_cost / cells_count
```

