def check_expression(expr):
    stack = []
    # Dictionary to hold matching pairs of parentheses
    matching_parentheses = {')': '(', '}': '{', ']': '['}

    for char in expr:
        if char in matching_parentheses.values():  # if it's an opening bracket
            stack.append(char)
        elif char in matching_parentheses.keys():  # if it's a closing bracket
            if stack and stack[-1] == matching_parentheses[char]:
                stack.pop()
            else:
                return False

    # If stack is empty, all parentheses were matched
    return not stack
```

